// Copies the Silero VAD v5 model (MIT, 2.3 MB) that ships in
// @ricky0123/vad-web into public/vad/, so live dictation loads it
// SAME-ORIGIN (the CSP allows no CDN) and only when the user starts
// dictation after downloading the speech model. public/vad/ is git-ignored
// and regenerated by predev/prebuild; nothing enters the startup bundle.
import { copyFileSync, existsSync, mkdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "..", "node_modules", "@ricky0123", "vad-web", "dist", "silero_vad_v5.onnx");
const outDir = join(here, "..", "public", "vad");

if (!existsSync(src)) {
  console.warn("copy-vad: @ricky0123/vad-web not installed — live dictation will fall back to no voice-activity detection");
  process.exit(0);
}
mkdirSync(outDir, { recursive: true });
const dest = join(outDir, "silero_vad_v5.onnx");
if (!existsSync(dest) || statSync(dest).size !== statSync(src).size) copyFileSync(src, dest);
console.log(`copy-vad: silero_vad_v5.onnx → public/vad/ (${(statSync(src).size / 1e6).toFixed(1)} MB)`);
